 if(!origin||!ex||!ey||!rect.width||!rect.height)return p.wanted;
 const x=(point.x-rect.left)*gunEffects.canvas.width/rect.width,y=(point.y-rect.top)*gunEffects.canvas.height/rect.height;
 const ax=(ex.x*ex.w-origin.x*origin.w)/100,ay=(ex.y*ex.w-origin.y*origin.w)/100,aw=(ex.w-origin.w)/100;
 const bx=(ey.x*ey.w-origin.x*origin.w)/100,by=(ey.y*ey.w-origin.y*origin.w)/100,bw=(ey.w-origin.w)/100;
 const a=ax-x*aw,b=bx-x*bw,c=ay-y*aw,d=by-y*bw,det=a*d-b*c;if(Math.abs(det)<1e-9)return p.wanted;
 const qx=(x-origin.x)*origin.w,qy=(y-origin.y)*origin.w,dx=(qx*d-b*qy)/det,dy=(a*qy-qx*c)/det;
 return Math.hypot(dx,dy)>8?Math.atan2(dy,dx):p.wanted;
