async function fullscreen(lock=true,toggle=false){
 if(fullscreenBusy)return !!fullscreenElement();
 fullscreenBusy=true;
 try{
  const root=document.documentElement;
  if(toggle&&fullscreenElement()){
   const exit=document.fullscreenElement?document.exitFullscreen:document.webkitExitFullscreen||document.webkitCancelFullScreen;
   if(exit)await exit.call(document);
  }else if(!fullscreenElement()){
   if(root.requestFullscreen){
    try{await root.requestFullscreen({navigationUI:'hide'});}
    catch(error){if(error?.name!=='TypeError'&&error?.name!=='NotSupportedError')throw error;await root.requestFullscreen();}
   }else{
    const request=root.webkitRequestFullscreen||root.webkitRequestFullScreen;
    if(request)await request.call(root);
   }
   if(!fullscreenElement()&&!lock)toast('Fullscreen is unavailable here. You can still play in landscape.',2.5);
  }
 }catch(_){if(!lock)toast('Fullscreen was blocked. You can still play in landscape.',2.5);}
 finally{fullscreenBusy=false;syncFullscreenButtons();queueViewportResize();}
 if(lock)try{await screen.orientation?.lock?.('landscape');}catch(_){}
 return !!fullscreenElement();
}

