function frame(stamp){if(viewCovered()){if(!paused)pauseForCoveredView();depotSound.pause();combatSound.stop();coldSound.stop();syncDepotUI();last=0;requestAnimationFrame(frame);return;}input.pollPad();const elapsed=(stamp-(last||stamp))/1000,dt=Math.min(.05,elapsed);last=stamp;if(renderer.quality.observe(elapsed,!document.hidden&&!paused&&['playing','loot','exiting'].includes(game.status)))syncGraphicsButtons();if(trace.active)trace.noteFrame(elapsed,paused?null:game,capture.active?capture.sync():null);const measureFrame=trace.active,frameBegin=measureFrame?performance.now():0;
 const wasOpening=depotSequence.opening;
 if(!paused&&['playing','loot','exiting'].includes(game.status)){
  if(wasOpening){const command=input.command(game,STEP);if(!paused){if(command.roll||command.fire)finishDepotOpening();else advanceDepotSequence(elapsed);}input.reset();acc=0;previousPlayer=null;}
  else advanceDepotSequence(dt);
 }else if(!['playing','loot','exiting'].includes(game.status)){depotSequence.cancel();}
 if(!paused&&!wasOpening&&['playing','loot','exiting'].includes(game.status)){acc+=dt;let loops=0;while(acc>=STEP&&loops++<8){const command=input.command(game,STEP);previousPlayer={...game.player,wave:game.wave,lives:game.lives};game.tick(STEP,command);const dashFx=Deadwatch3D.advanceDashTrail(visual.dashTrail,game);visual.dashTrail=dashFx.state;if(dashFx.effect)visual.pool.spawn(dashFx.effect);if(trace.active)trace.sample(game,command,{touchAim:!!input.touchAimActive,aimPad:!!input.padAimActive,fireDrag:!!input.fireAimActive,fireHeld:!!input.fireHeld,interactHeld:!!input.interactHeld},renderer.getPresentationMetrics(),capture.sync());events();acc-=STEP;handleStatus();if(paused)break;}}const simulationEnd=measureFrame?performance.now():0;visual.depotSequence=depotSequence.view(game);syncDepotUI();depotSound.sync(visual.depotSequence,paused||!['playing','loot','exiting'].includes(game.status));coldSound.sync(game,paused||!['playing','loot','exiting'].includes(game.status));updateFx(dt);hud();visual.renderPlayer=!paused&&['playing','loot','exiting'].includes(game.status)&&previousPlayer?.wave===game.wave&&previousPlayer?.lives===game.lives?Deadwatch3D.interpolatePlayer(previousPlayer,game.player,acc/STEP):null;const renderBegin=measureFrame?performance.now():0;if(game.status==='menu')renderMenuBackdrop();else renderer.render(Deadwatch3D.buildRenderSnapshot(game,visual),dt,visual);const renderEnd=measureFrame?performance.now():0;gunEffects.render(game,dt);const overlayEnd=measureFrame?performance.now():0;compositeCapture(stamp);if(measureFrame){const end=performance.now();trace.noteWork({simulationMs:simulationEnd-frameBegin,uiEffectsMs:renderBegin-simulationEnd,worldMs:renderEnd-renderBegin,gunEffectsMs:overlayEnd-renderEnd,captureMs:end-overlayEnd,totalMs:end-frameBegin,quality:renderer.quality.mode,qualityLevel:renderer.quality.level,recording:!!capture.active});}requestAnimationFrame(frame);}

function renderProfile(){
 const data=progression.data,rank=P.rank(data.xp),skin=P.SKINS.find(s=>s.id===data.selected)||P.SKINS[0];visual.playerTint=skin.tint;
 renderWatchUI();renderReplaySetup();$('profileLevel').textContent='WATCH RANK '+rank.level;$('profileCredits').textContent=data.credits+' CREDITS';$('profileXP').textContent=rank.max?'MAX LEVEL':rank.progress+' / '+rank.needed+' XP';$('profileXPFill').style.width=(rank.max?100:100*rank.progress/rank.needed)+'%';
 $('profileSummary').textContent=data.stats.runs+' RUNS · BEST ROUND '+data.stats.bestWave+' · '+data.stats.kills+' KILLS';
 $('runEligibility').textContent=game.godMode?'TEST MODE · Turn God Mode off to earn XP and credits.':'WATCH XP · Campaign clears, completed Quick Matches and five-round Endless blocks. No XP for kills.';
 $('lockerSummary').textContent='EQUIPPED · '+skin.name.toUpperCase();
 $('profileSaveStatus').textContent=progression.notice||(progression.saved?'Saved in this browser. Export before opening a new build.':'Progress stays here until you export or save.');
 for(const item of P.SKINS){const button=$('skin-'+item.id),owned=data.owned.includes(item.id),selected=data.selected===item.id;button.dataset.selected=String(selected);button.setAttribute('aria-pressed',String(selected));button.disabled=!owned&&(rank.level<item.level||data.credits<item.cost);button.querySelector('.skinStatus').textContent=selected?'EQUIPPED':owned?'EQUIP':rank.level<item.level?'LEVEL '+item.level+' · '+item.cost+' CR':item.cost+' CREDITS · UNLOCK';}
 for(const milestone of P.MILESTONES){const el=$('milestone-'+milestone.wave),done=data.milestones.includes(milestone.wave);el.dataset.done=String(done);el.textContent='ROUND '+milestone.wave+' · '+(done?'CLAIMED':'+'+milestone.credits+' COSMETIC CR');}
}
function finishRun(reason){
 if(!activeRun||activeRun.finished)return activeRun?.result||null;
 const result=progression.settle(activeRun,game,reason);renderProfile();
 if(trace.active)trace.recordEvent({type:'run_rewards',...result},game,capture.sync());return result;
}
function renderRunRewards(reward){
 if(!reward)return;
 $('rewardXP').textContent=reward.xp+' WATCH XP BANKED';$('rewardCredits').textContent='+'+reward.credits+' CREDITS';
 $('rewardDetail').textContent=reward.practice?'TEST RUN · God Mode and Shooting Range do not earn progression.':reward.kills+' kills · '+reward.cleared+' rounds cleared'+(reward.milestones.length?' · New milestones: '+reward.milestones.join(', '):'');
 $('rewardLevel').textContent=reward.levelAfter>reward.levelBefore?'WATCH RANK '+reward.levelBefore+' → '+reward.levelAfter:'WATCH RANK '+reward.levelAfter;
 $('rewardSave').textContent=progression.notice||(reward.practice?'Turn God Mode off in the menu for an earning run.':'Earned Watch XP is already banked. Spend Upgrade Points in Upgrades.');
}
function openLocker(){renderProfile();show('profileOverlay');}
function exportProfile(){downloadBlob(new Blob([progression.exportJSON()],{type:'application/json'}),'Deadwatch_Profile.json');toast('PROFILE EXPORTED',1.2);}
async function importProfileFile(event){
 const file=event.target.files?.[0];event.target.value='';if(!file)return;
 try{
  if(file.size>262144)throw Error('Profile file is too large.');
  const data=progression.parseImport(await file.text()),rank=P.rank(data.xp);
  if(!await confirmInGame('LOAD PROFILE?','Watch Rank '+rank.level+' · '+data.credits+' credits.\nThis replaces the profile saved in this browser.','LOAD PROFILE'))return;
  progression.importProfile(data);renderProfile();toast(progression.saved?'PROFILE LOADED':'PROFILE LOADED · EXPORT TO KEEP IT',1.5);
 }catch(_){toast('COULD NOT LOAD PROFILE · CURRENT SAVE KEPT',1.8);}
}

function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function downloadDiagnostics(){
 if(!trace.data){setDiagnosticsEnabled(true);toast(['playing','loot','exiting'].includes(game.status)?'DIAGNOSTICS ON · RESUME TO RECORD':'DIAGNOSTICS ON · START ANOTHER WATCH',1.5);return;}
 diagnosticsEnabled=false;
 if(trace.active)trace.finish(game,'manual-save',capture.sync());
 toast('BUILDING TRACE + VIDEO…',1.2);
 const videoBlob=await capture.stop(),sessionId=trace.data.meta.sessionId||capture.sessionId||DeadwatchCapture.makeSessionId(),cap={...capture.meta(),...capture.sync(),durationMs:capture.sync().videoTimeMs};
 trace.data.meta.capture={...(trace.data.meta.capture||{}),...cap};if(trace.data.summary)trace.data.summary.capture=cap;
 const traceName=`Deadwatch_0.36.38_trace_${sessionId}.json`,videoName=`Deadwatch_0.36.38_gameplay_${sessionId}.${DeadwatchCapture.extForMime(capture.mimeType)}`;
 if(videoBlob&&videoBlob.size){trace.data.meta.capture.file=videoName;const manifest={schema:'deadwatch-diagnostic-v1',build:trace.build,sessionId,createdAt:trace.data.meta.createdAt,traceFile:traceName,videoFile:videoName,videoMimeType:capture.mimeType||videoBlob.type||'video/webm',alignment:'Use sample.sync.videoTimeMs and event.sync.videoTimeMs as the exact position in gameplay video.',capture:cap};const traceBlob=new Blob([trace.exportJSON()],{type:'application/json'}),manifestBlob=new Blob([JSON.stringify(manifest,null,2)],{type:'application/json'}),zip=await DeadwatchCapture.storeZip([{name:'manifest.json',data:manifestBlob},{name:traceName,data:traceBlob},{name:videoName,data:videoBlob}]);downloadBlob(zip,`Deadwatch_0.36.38_diagnostic_${sessionId}.zip`);toast('TRACE + VIDEO SAVED',1.1);}else{downloadBlob(new Blob([trace.exportJSON()],{type:'application/json'}),traceName);toast('VIDEO UNSUPPORTED · TRACE SAVED',1.2);}
}
window.__deadwatchTrace=trace;window.__deadwatchCapture=capture;
window.__deadwatchDiagnostics={get enabled(){return diagnosticsEnabled;},setEnabled:setDiagnosticsEnabled};syncDiagnosticsButtons();

