// .155 replay setup uses only the saved Campaign clear list.
function replayMapOptions(select){
 const previous=select.value,unlocked=progression.data.watch.mapsCompleted;select.replaceChildren();
 if(!C.ARENAS.some(a=>unlocked.includes(a.id))){const option=document.createElement('option');option.value='';option.textContent='Clear a map in Campaign to unlock it';select.append(option);}
 for(const arena of C.ARENAS){const option=document.createElement('option');option.value=arena.id;option.disabled=!unlocked.includes(arena.id);option.textContent=arena.name+(option.disabled?' · LOCKED':'');select.append(option);}
 if(unlocked.includes(previous))select.value=previous;else select.value=C.ARENAS.find(a=>unlocked.includes(a.id))?.id||'';
}
let replaySelectedMaps=null,replayAllMaps=true;
function renderReplaySetup(){
 const unlocked=C.ARENAS.filter(a=>progression.data.watch.mapsCompleted.includes(a.id)).map(a=>a.id);
 replayMapOptions($('quickMap'));replayMapOptions($('endlessMap'));
 if(replaySelectedMaps===null||replayAllMaps)replaySelectedMaps=[...unlocked];else replaySelectedMaps=replaySelectedMaps.filter(id=>unlocked.includes(id));
 const grid=$('rotationMaps');grid.replaceChildren();
 for(const arena of C.ARENAS){const label=document.createElement('label'),input=document.createElement('input'),text=document.createElement('span');
  input.type='checkbox';input.value=arena.id;input.disabled=!unlocked.includes(arena.id);input.checked=replaySelectedMaps.includes(arena.id);text.textContent=arena.name+(input.disabled?' · LOCKED':'');
  input.onchange=()=>{replaySelectedMaps=Array.from(grid.querySelectorAll('input:checked')).map(e=>e.value);replayAllMaps=unlocked.every(id=>replaySelectedMaps.includes(id));syncReplaySetup();};label.append(input,text);grid.append(label);
 }
 syncReplaySetup();
}
function syncReplaySetup(){
 const w=progression.data.watch,unlocked=C.ARENAS.filter(a=>w.mapsCompleted.includes(a.id)),rotation=$('endlessMapType').value==='rotation',records=w.endlessRecords;
 $('endlessSingleField').hidden=rotation;$('endlessRotationField').hidden=!rotation;
 $('rotationAll').checked=unlocked.length>0&&unlocked.every(a=>replaySelectedMaps?.includes(a.id));$('rotationAll').disabled=!unlocked.length;
 $('quickStart').disabled=!unlocked.some(a=>a.id===$('quickMap').value)||progression.blocked;
 $('endlessStart').disabled=progression.blocked||(rotation?!replaySelectedMaps?.length:!unlocked.some(a=>a.id===$('endlessMap').value));
 $('quickLocked').textContent=unlocked.length?unlocked.length+' / 8 MAPS UNLOCKED · Clear more maps in Campaign.':'Complete your first Campaign map to unlock Quick Match.';
 $('endlessLocked').textContent=unlocked.length?'Only maps you have cleared in Campaign can be deployed.':'Complete your first Campaign map to unlock Endless.';
 $('endlessRecords').textContent='SOLO '+records.solo+' · WITH TEAMMATE '+records.teammate+' · ROTATION '+records.rotation;
 const maps=rotation?C.ARENAS.filter(a=>replaySelectedMaps?.includes(a.id)):C.ARENAS.filter(a=>a.id===$('endlessMap').value);
 $('endlessMapRecord').textContent=maps.length?maps.map(a=>a.name+': Round '+(records.maps[a.id]||0)).join(' · '):'Select at least one unlocked map.';
 $('rotationOrder').textContent=rotation&&maps.length?'DEPLOYMENT ORDER · '+maps.map(a=>a.name).join(' → '):'';
}
function startReplay(mode,again=false){
 game.setReplayUnlockedMaps(progression.data.watch.mapsCompleted);
 let setup;
 if(again)setup=game.replaySetup;
 else{const prefix=mode==='quick'?'quick':'endless',rotation=mode==='endless'&&$('endlessMapType').value==='rotation';setup={maps:rotation?C.ARENAS.filter(a=>replaySelectedMaps.includes(a.id)).map(a=>a.id):[$(prefix+'Map').value],rotation,team:$(prefix+'Team').value==='team',difficulty:$(prefix+'Difficulty').value};}
 try{game.configureReplay(mode,setup);}catch(error){toast(error.message,2);return;}
 start(mode);syncSquadButtons();
}
